import logging
import os
from taf.rfrl.ue.helpers.calculator import Calculator
from taf.rfrl.ue.exceptions import DataTransferVerificationFailure, RadioBearerVerificationFailure
from taf.rfrl.ue.parsers.tput_kpi_parsers import L1L2TracesKPIParser
from taf.rfrl.utilities.robot.general import get_builtin_instance
from taf.rfrl.utilities.test_config import get_log_path


def start_data_transfer_on_real_ue(dt_name, ue_alias, direction, protocol, duration, tput, parallel_streams,
                                   size_packet, buffer_client=None, buffer_server=None, interval=None, qci=None,
                                   linux_congestion=None, multi_radio_bearer=False,
                                   ping_appserver_before_data_transfer=False):
    ue = get_builtin_instance('ue')
    tput_args = _get_tput_args(dt_name, ue_alias, direction, protocol.lower(), duration, tput, parallel_streams,
                               size_packet, buffer_client=buffer_client, buffer_server=buffer_server,
                               interval=interval, qci=qci, linux_congestion=linux_congestion,
                               multi_radio_bearer=multi_radio_bearer)
    if ping_appserver_before_data_transfer:
        ue.start_data_transfer(dt_name='PING', ue_alias=ue_alias, direction='dl', protocol='icmp', duration='10s')
    ue.start_data_transfer(**tput_args)


def get_average_throuhput_value(direction):
    ue = get_builtin_instance('ue')
    tput_data = ue.get_data_transfer_statistics(direction.upper()).split(';')
    logging.debug("{} TPUT DATA: {}".format(direction.upper(), tput_data))
    return float(tput_data[0].split(',')[0])


def verify_average_throughput_for_multi_radio_bearers(direction, tput, expected_tput, deviation):
    admissible_tput_value = Calculator().calculate_admissible_tput_value(deviation, expected_tput)
    default_radio_bearer_tput_value = get_average_throuhput_value('DT_{}_DEFAULT'.format(direction)) / 1000
    dedicated_radio_bearer_tput_value = get_average_throuhput_value('DT_{}_DEDICATED'.format(direction)) / 1000
    avg_tput_value = default_radio_bearer_tput_value + dedicated_radio_bearer_tput_value
    is_tput_value_admissible = admissible_tput_value['min'] <= avg_tput_value <= admissible_tput_value['max']
    if is_tput_value_admissible:
        logging.info("Expected throughput range of value: {} - {} [Kbits/sec]"
                     "\nActual average tput: {} [Kbits/sec]".format(admissible_tput_value['min'],
                                                                    admissible_tput_value['max'], avg_tput_value))
    else:
        raise DataTransferVerificationFailure("\nBased on values provided: tput: {} [Kbits/sec], deviation: {}"
                                              "\nExpected throughput range of value: {} - {} [Kbits/sec]"
                                              "\nActual average tput: {} [Kbits/sec]".format(
                                                  tput, deviation, admissible_tput_value['min'],
                                                  admissible_tput_value['max'],
                                                  avg_tput_value))


def _get_tput_args(dt_name, ue_alias, direction, protocol, duration, tput, parallel_streams,
                   size_packet, **kwargs):
    tput_per_stream = Calculator().calculate_tput_per_stream(parallel_streams, total_tput=tput)
    tput_args = {
        'dt_name': dt_name,
        'ue_alias': ue_alias,
        'direction': direction,
        'protocol': protocol,
        'duration': duration,
        'parallel_streams': parallel_streams
    }

    for arg_name in kwargs:
        if kwargs[arg_name]:
            if arg_name == 'multi_radio_bearer' and kwargs[arg_name] is True:
                if protocol.lower() == 'udp':
                    tput_args['port'] = 9991
                elif protocol.lower() == 'tcp':
                    tput_args['port'] = 9992
            else:
                tput_args[arg_name] = kwargs[arg_name]

    if protocol.lower() == 'udp':
        tput_args['throughput'] = tput_per_stream
        tput_args['packet'] = size_packet
    elif protocol.lower() == 'tcp':
        tput_args['max_segment_size'] = size_packet

    return tput_args


def parse_pcap(pcap_dir=None, sub_dir='data_transfer', display_filter='None'):
    if not pcap_dir:
        pcap_dir = os.path.join(get_log_path(), sub_dir).strip()
    pcap_file = None
    for new_file in os.listdir(pcap_dir):
        if new_file.endswith('pcap') or new_file.endswith('pcap0'):
            pcap_file = new_file
            break
    parser = L1L2TracesKPIParser()
    return parser.convert_pcap_to_pdml(os.path.join(pcap_dir, pcap_file), display_filter)


def verify_teid_values(pcap_dir, protocol='udp'):
    parser = L1L2TracesKPIParser()
    teid_values = parser.get_teid_values(pcap_dir, protocol)
    if teid_values['dedicated_bearer_teid'] == teid_values['default_bearer_teid']:
        raise RadioBearerVerificationFailure("Dedicated radio bearer has the same teid as default radio bearer"
                                             " equal: {}".format(teid_values['dedicated_bearer_teid']))
    else:
        logging.debug('Dedicated radio bearer teid: {}\n'
                      'Default radio bearer teid: {}'.format(teid_values['dedicated_bearer_teid'],
                                                             teid_values['default_bearer_teid']))
